players=json.loads((ROOT/'data/players-2026-08-19.json').read_text(encoding='utf-8'))
expected={p['id'] for p in players if p.get('stat_source_status')=='projection'}
ids=[x['id'] for x in R]
if len(ids)!=50 or len(set(ids))!=50:
    raise SystemExit(f'projection manifest needs 50 unique rows, got {len(ids)} / {len(set(ids))}')
